type ParseError struct{ Line int }
func (e *ParseError) Error() string { return fmt.Sprintf("line %d", e.Line) }

func parse(ok bool) *ParseError {
    if ok { return nil }
    return &ParseError{Line: 7}
}

var err1 error = parse(true)   // healthy path
var err2 error                  // declared, never assigned
err3 := parse(true)             // note: concrete type, no interface

Q1: err1 == nil — true or false?
Q2: err2 == nil — true or false?
Q3: err3 == nil — true or false?
Q4: what does fmt.Printf("%v / %#v", err1, err1) print, roughly?

